apply_patch <<'PATCH'
*** Begin Patch
*** Add File: output/styles.css
+:root{
+  --bg: #ffffff;
+  --text: #0b1220;
+  --muted: #52627a;
+
+  --primary: #0066ff;
+  --primary-700: #0052cc;
+  --teal: #13b8a6;
+  --teal-700: #0f9486;
+
+  --surface: #ffffff;
+  --surface-2: #f4f7fb;
+  --border: rgba(15, 30, 50, 0.10);
+
+  --shadow-sm: 0 6px 18px rgba(10, 25, 55, 0.08);
+  --shadow-md: 0 14px 40px rgba(10, 25, 55, 0.12);
+
+  --radius-lg: 18px;
+  --radius-md: 14px;
+  --radius-sm: 12px;
+
+  --focus: 0 0 0 4px rgba(0, 102, 255, 0.18);
+}
+
+*{box-sizing:border-box}
+html,body{height:100%}
+body{
+  margin:0;
+  font-family: Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
+  color:var(--text);
+  background: radial-gradient(1200px 500px at 50% -100px, rgba(0,102,255,0.10), transparent 65%), var(--bg);
+  line-height:1.5;
+}
+
+a{color:inherit; text-decoration:none}
+img{max-width:100%; display:block}
+
+.container{
+  width:min(1120px, calc(100% - 40px));
+  margin-inline:auto;
+}
+
+.skip-link{
+  position:absolute;
+  left:-999px;
+  top:10px;
+  background:var(--text);
+  color:#fff;
+  padding:10px 12px;
+  border-radius:10px;
+  z-index:9999;
+}
+.skip-link:focus{left:10px}
+
+.sr-only{
+  position:absolute;
+  width:1px;
+  height:1px;
+  padding:0;
+  margin:-1px;
+  overflow:hidden;
+  clip:rect(0,0,0,0);
+  white-space:nowrap;
+  border:0;
+}
+
+/* Header */
+.site-header{
+  position:sticky;
+  top:0;
+  z-index:50;
+  background: rgba(255,255,255,0.8);
+  backdrop-filter: blur(10px);
+  border-bottom: 1px solid var(--border);
+}
+
+.header-inner{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  padding:14px 0;
+  gap:14px;
+}
+
+.brand{
+  display:flex;
+  align-items:center;
+  gap:10px;
+  font-weight:800;
+  letter-spacing:-0.02em;
+}
+.brand-mark{
+  width:34px;
+  height:34px;
+  border-radius:12px;
+  background: linear-gradient(135deg, rgba(0,102,255,0.18), rgba(19,184,166,0.18));
+  display:grid;
+  place-items:center;
+  border:1px solid var(--border);
+}
+.brand-mark svg{width:18px; height:18px; fill: var(--primary)}
+.brand-name{font-size:18px}
+
+.nav{display:flex; align-items:center; gap:18px}
+.nav-link{font-weight:600; color: rgba(11,18,32,0.82)}
+.nav-link:hover{color: rgba(11,18,32,1)}
+
+.icon-btn{
+  border:1px solid var(--border);
+  background:var(--surface);
+  border-radius:12px;
+  width:44px;
+  height:44px;
+  display:grid;
+  place-items:center;
+  cursor:pointer;
+  box-shadow: var(--shadow-sm);
+}
+.icon-btn svg{width:22px; height:22px; fill: rgba(11,18,32,0.82)}
+.icon-btn:focus-visible{outline:none; box-shadow: var(--shadow-sm), var(--focus)}
+
+.mobile-menu-btn{display:none}
+
+/* Buttons */
+.btn{
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap:10px;
+  padding:12px 16px;
+  border-radius: 14px;
+  border:1px solid transparent;
+  font-weight:700;
+  cursor:pointer;
+  transition: transform .12s ease, box-shadow .12s ease, background .12s ease, border-color .12s ease;
+  user-select:none;
+}
+.btn:focus-visible{outline:none; box-shadow: var(--shadow-sm), var(--focus)}
+.btn:active{transform: translateY(1px)}
+
+.btn-primary{
+  background: linear-gradient(135deg, var(--primary), #2f83ff);
+  color:#fff;
+  box-shadow: 0 12px 30px rgba(0,102,255,0.22);
+}
+.btn-primary:hover{background: linear-gradient(135deg, var(--primary-700), #2b79f4)}
+
+.btn-ghost{
+  background: rgba(255,255,255,0.7);
+  border-color: var(--border);
+  color: rgba(11,18,32,0.86);
+}
+.btn-ghost:hover{background: #fff}
+
+.btn-lg{padding:14px 18px; border-radius: 16px}
+.btn-sm{padding:10px 12px; border-radius: 12px; font-size:14px}
+
+/* Hero */
+.hero{padding: 56px 0 12px}
+.hero-grid{
+  display:grid;
+  grid-template-columns: 1.15fr 0.85fr;
+  gap: 28px;
+  align-items:center;
+}
+
+.pill{
+  display:inline-flex;
+  align-items:center;
+  gap:10px;
+  padding:8px 12px;
+  border-radius: 999px;
+  background: rgba(255,255,255,0.7);
+  border:1px solid var(--border);
+  color: rgba(11,18,32,0.78);
+  font-weight:600;
+  box-shadow: var(--shadow-sm);
+}
+.pill-dot{width:10px; height:10px; border-radius:999px; background: var(--teal)}
+
+h1{
+  font-size: clamp(34px, 4vw, 54px);
+  line-height:1.05;
+  margin:14px 0 12px;
+  letter-spacing:-0.04em;
+}
+
+.lead{font-size: 18px; color: rgba(11,18,32,0.80); margin:0 0 18px}
+
+.hero-cta-row{display:flex; gap:12px; flex-wrap:wrap}
+
+.trust-row{
+  margin-top: 22px;
+  display:grid;
+  grid-template-columns: repeat(4, minmax(0, 1fr));
+  gap:12px;
+}
+.stat{
+  background: rgba(255,255,255,0.72);
+  border:1px solid var(--border);
+  border-radius: 16px;
+  padding:12px 12px;
+  box-shadow: var(--shadow-sm);
+}
+.stat-k{font-weight:800; letter-spacing:-0.02em}
+.stat-l{font-size:13px; color: rgba(11,18,32,0.62)}
+
+.hero-visual{position:relative; min-height: 360px}
+.blob{
+  position:absolute;
+  inset: 18px 10px 0 34px;
+  border-radius: 28px;
+  background: radial-gradient(600px 260px at 30% 25%, rgba(0,102,255,0.28), transparent 60%),
+              radial-gradient(520px 260px at 80% 60%, rgba(19,184,166,0.30), transparent 60%),
+              linear-gradient(180deg, rgba(255,255,255,0.55), rgba(255,255,255,0.25));
+  border:1px solid var(--border);
+  box-shadow: var(--shadow-md);
+  transform: rotate(-2deg);
+}
+
+.card-stack{position:absolute; inset: 32px 0 0 0; display:grid; gap:12px; align-content:start; padding: 0 10px}
+.mini-card{
+  display:flex;
+  align-items:center;
+  gap:12px;
+  background: rgba(255,255,255,0.86);
+  border:1px solid var(--border);
+  border-radius: 16px;
+  padding: 12px 12px;
+  box-shadow: var(--shadow-sm);
+  transform: translateX(12px);
+}
+.mini-card:nth-child(2){transform: translateX(30px)}
+.mini-card:nth-child(3){transform: translateX(18px)}
+
+.mini-icon{
+  width:40px;
+  height:40px;
+  border-radius: 14px;
+  display:grid;
+  place-items:center;
+  background: rgba(0,102,255,0.12);
+  color: var(--primary);
+  font-weight:900;
+}
+.mini-title{font-weight:800; letter-spacing:-0.02em}
+.mini-sub{font-size:13px; color: rgba(11,18,32,0.62)}
+
+/* Sections */
+.section{padding: 56px 0}
+.section-muted{background: var(--surface-2)}
+.section-head{display:flex; align-items:flex-end; justify-content:space-between; gap:16px; margin-bottom: 18px}
+.section-head h2{margin:0; font-size: 32px; letter-spacing:-0.03em}
+.muted{color: var(--muted)}
+
+/* Search */
+.search{padding: 18px 0 34px}
+.search-surface{
+  background: rgba(255,255,255,0.85);
+  border:1px solid var(--border);
+  border-radius: 22px;
+  box-shadow: var(--shadow-md);
+  padding: 22px;
+}
+.search-head{display:flex; align-items:baseline; justify-content:space-between; gap:12px; flex-wrap:wrap; margin-bottom: 14px}
+.search-head h2{margin:0; font-size: 26px; letter-spacing:-0.02em}
+.search-head p{margin:0}
+
+.search-form{
+  display:grid;
+  grid-template-columns: 1.5fr 1fr 1fr auto;
+  gap: 12px;
+  align-items:end;
+}
+
+.field label{display:block; font-weight:700; margin-bottom: 8px; font-size: 14px}
+.control{position:relative; display:flex; align-items:center; gap:10px}
+.field-icon{
+  position:absolute;
+  left: 12px;
+  width: 20px;
+  height: 20px;
+  display:grid;
+  place-items:center;
+}
+.field-icon svg{width:18px; height:18px; fill: rgba(11,18,32,0.55)}
+
+input, select{
+  width:100%;
+  height: 52px;
+  border-radius: 16px;
+  border: 1px solid var(--border);
+  background: #fff;
+  padding: 0 12px 0 40px;
+  font-size: 16px;
+  color: var(--text);
+  box-shadow: 0 0 0 rgba(0,0,0,0);
+  transition: box-shadow .12s ease, border-color .12s ease;
+}
+select{padding-right: 38px}
+input:focus, select:focus{outline:none; border-color: rgba(0,102,255,0.55); box-shadow: var(--focus)}
+
+.chip{
+  position:absolute;
+  right:10px;
+  top:50%;
+  transform: translateY(-50%);
+  border:1px solid rgba(19,184,166,0.28);
+  background: rgba(19,184,166,0.12);
+  color: rgba(4, 110, 100, 1);
+  border-radius: 999px;
+  padding: 8px 10px;
+  font-weight:800;
+  font-size: 13px;
+  cursor:pointer;
+  transition: background .12s ease, transform .12s ease;
+}
+.chip:hover{background: rgba(19,184,166,0.18)}
+.chip:focus-visible{outline:none; box-shadow: var(--focus)}
+
+.form-hint{
+  grid-column: 1 / -1;
+  min-height: 22px;
+  font-size: 14px;
+  color: rgba(11,18,32,0.72);
+}
+
+/* Autocomplete */
+.autocomplete{position:relative}
+.suggestions{
+  position:absolute;
+  left:0;
+  right:0;
+  top: calc(100% + 8px);
+  background: #fff;
+  border: 1px solid var(--border);
+  border-radius: 16px;
+  box-shadow: var(--shadow-md);
+  overflow:hidden;
+  display:none;
+  z-index: 20;
+}
+.suggestions.open{display:block}
+.suggestions .item{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:12px;
+  padding: 12px 12px;
+  cursor:pointer;
+}
+.suggestions .item:hover{background: rgba(0,102,255,0.06)}
+.suggestions .item[aria-selected="true"]{background: rgba(0,102,255,0.10)}
+.s-left{display:flex; align-items:center; gap:10px}
+.badge{
+  font-size: 12px;
+  font-weight:900;
+  border-radius: 999px;
+  padding: 4px 8px;
+  background: rgba(0,102,255,0.10);
+  color: rgba(0,82,204,1);
+  border:1px solid rgba(0,102,255,0.18);
+}
+.kbd{
+  font-size: 12px;
+  color: rgba(11,18,32,0.55);
+  border: 1px solid rgba(15, 30, 50, 0.12);
+  border-bottom-width:2px;
+  border-radius: 10px;
+  padding: 4px 8px;
+  background: rgba(244,247,251,0.75);
+}
+
+/* Cards */
+.cards{
+  display:grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 14px;
+}
+.card{
+  border:1px solid var(--border);
+  background: #fff;
+  border-radius: 18px;
+  padding: 16px;
+  box-shadow: var(--shadow-sm);
+  transition: transform .12s ease, box-shadow .12s ease, border-color .12s ease;
+  min-height: 120px;
+}
+.card:hover{transform: translateY(-2px); box-shadow: var(--shadow-md); border-color: rgba(0,102,255,0.20)}
+.card:focus-visible{outline:none; box-shadow: var(--shadow-md), var(--focus)}
+.card-icon{
+  width:48px;
+  height:48px;
+  border-radius: 18px;
+  background: rgba(0,102,255,0.10);
+  display:grid;
+  place-items:center;
+  border:1px solid rgba(0,102,255,0.14);
+  margin-bottom: 10px;
+}
+.card-icon svg{width:24px; height:24px; fill: rgba(0,82,204,1)}
+.card-title{font-weight:900; letter-spacing:-0.02em; margin-bottom: 4px}
+.card-sub{color: rgba(11,18,32,0.65); font-size: 14px}
+
+/* Steps */
+.steps{
+  display:grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 14px;
+}
+.step{
+  border:1px solid var(--border);
+  background: rgba(255,255,255,0.85);
+  border-radius: 18px;
+  padding: 16px;
+  box-shadow: var(--shadow-sm);
+}
+.step-num{
+  width:36px;
+  height:36px;
+  border-radius: 999px;
+  background: rgba(19,184,166,0.14);
+  color: rgba(4,110,100,1);
+  display:grid;
+  place-items:center;
+  font-weight:900;
+  margin-bottom: 10px;
+}
+.step h3{margin:0 0 8px; letter-spacing:-0.02em}
+.step p{margin:0; color: rgba(11,18,32,0.72)}
+
+/* Testimonials */
+.quotes{
+  display:grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 14px;
+}
+.quote{
+  margin:0;
+  border:1px solid var(--border);
+  background: #fff;
+  border-radius: 18px;
+  padding: 16px;
+  box-shadow: var(--shadow-sm);
+}
+.quote blockquote{margin:0 0 12px; color: rgba(11,18,32,0.80); font-size: 16px}
+.quote figcaption{display:flex; gap:10px; align-items:baseline}
+
+/* App Promo */
+.app-grid{display:grid; grid-template-columns: 1.1fr 0.9fr; gap: 18px; align-items:center}
+.checks{margin: 16px 0 0; padding:0; list-style:none; display:grid; gap:10px}
+.checks li{
+  padding-left: 28px;
+  position:relative;
+  color: rgba(11,18,32,0.80);
+}
+.checks li::before{
+  content:"";
+  position:absolute;
+  left:0;
+  top: 4px;
+  width:18px;
+  height:18px;
+  border-radius: 6px;
+  background: rgba(19,184,166,0.16);
+  border:1px solid rgba(19,184,166,0.22);
+}
+.checks li::after{
+  content:"";
+  position:absolute;
+  left: 6px;
+  top: 10px;
+  width: 8px;
+  height: 4px;
+  border-left: 2px solid rgba(4,110,100,1);
+  border-bottom: 2px solid rgba(4,110,100,1);
+  transform: rotate(-45deg);
+}
+
+.store-row{display:flex; gap:12px; flex-wrap:wrap; margin-top: 18px}
+.store{
+  display:flex;
+  flex-direction:column;
+  gap:2px;
+  padding: 12px 14px;
+  border-radius: 16px;
+  background: #fff;
+  border:1px solid var(--border);
+  box-shadow: var(--shadow-sm);
+  min-width: 190px;
+  transition: transform .12s ease, box-shadow .12s ease;
+}
+.store:hover{transform: translateY(-2px); box-shadow: var(--shadow-md)}
+.store-k{font-size:12px; color: rgba(11,18,32,0.62); font-weight:700}
+.store-v{font-size:18px; font-weight:900; letter-spacing:-0.02em}
+
+.phone{
+  width: min(360px, 100%);
+  margin-inline:auto;
+  border-radius: 34px;
+  border: 1px solid rgba(15, 30, 50, 0.16);
+  background: linear-gradient(180deg, rgba(255,255,255,0.75), rgba(255,255,255,0.25));
+  box-shadow: var(--shadow-md);
+  padding: 12px;
+}
+.phone-top{height: 18px; width: 46%; margin: 4px auto 12px; border-radius: 999px; background: rgba(15,30,50,0.08)}
+.phone-screen{
+  background: #fff;
+  border-radius: 24px;
+  border:1px solid rgba(15,30,50,0.10);
+  padding: 14px;
+  display:grid;
+  gap: 12px;
+}
+.phone-card{
+  border:1px solid rgba(15, 30, 50, 0.10);
+  border-radius: 18px;
+  padding: 14px;
+  background: radial-gradient(300px 120px at 20% 0%, rgba(0,102,255,0.09), transparent 60%), #fff;
+}
+.pc-title{font-weight:900; letter-spacing:-0.02em}
+.pc-sub{color: rgba(11,18,32,0.62); margin-top: 2px; font-size: 13px}
+.pc-row{display:flex; gap:8px; margin-top: 10px; flex-wrap:wrap}
+.pc-pill{font-size: 12px; font-weight:900; border-radius: 999px; padding: 4px 8px; background: rgba(244,247,251,0.9); border:1px solid rgba(15, 30, 50, 0.10); color: rgba(11,18,32,0.70)}
+.pc-btn{margin-top: 12px; display:inline-flex; padding: 10px 12px; border-radius: 14px; background: linear-gradient(135deg, var(--teal), #31d6c4); color: #fff; font-weight:900; width: 92px; justify-content:center}
+
+/* Footer */
+.footer{background: #0b1220; color: rgba(255,255,255,0.86)}
+.footer-grid{padding: 42px 0 22px; display:grid; grid-template-columns: 0.9fr 1.6fr; gap: 18px; align-items:start}
+.brand-footer .brand-mark{background: rgba(255,255,255,0.08); border-color: rgba(255,255,255,0.12)}
+.brand-footer .brand-mark svg{fill: #6ea8ff}
+.footer a{color: rgba(255,255,255,0.80)}
+.footer a:hover{color: rgba(255,255,255,1)}
+.footer-cols{display:grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px}
+.footer-col h3{margin:0 0 10px; font-size: 14px; letter-spacing:0.02em; text-transform:uppercase; color: rgba(255,255,255,0.62)}
+.footer-col a{display:block; padding: 6px 0; font-weight:600}
+
+.footer-bottom{border-top: 1px solid rgba(255,255,255,0.12); padding: 14px 0 22px; display:flex; align-items:center; justify-content:space-between; gap: 12px; flex-wrap:wrap}
+.backtop{font-weight:800}
+
+/* Drawer */
+.drawer{position:fixed; inset:0; z-index:60; pointer-events:none}
+.drawer.open{pointer-events:auto}
+.drawer-backdrop{position:absolute; inset:0; background: rgba(11,18,32,0.44); opacity:0; transition: opacity .18s ease}
+.drawer.open .drawer-backdrop{opacity:1}
+.drawer-panel{
+  position:absolute;
+  right:0;
+  top:0;
+  height:100%;
+  width: min(340px, 92vw);
+  background: #fff;
+  transform: translateX(102%);
+  transition: transform .18s ease;
+  box-shadow: var(--shadow-md);
+  display:flex;
+  flex-direction:column;
+}
+.drawer.open .drawer-panel{transform: translateX(0)}
+.drawer-header{display:flex; align-items:center; justify-content:space-between; padding: 14px; border-bottom: 1px solid var(--border)}
+.drawer-brand{display:flex; align-items:center; gap:10px; font-weight:900}
+.drawer-nav{display:grid; gap: 10px; padding: 14px}
+.drawer-link{padding: 12px 12px; border-radius: 14px; border:1px solid var(--border); font-weight:900}
+.drawer-link:hover{background: rgba(0,102,255,0.06)}
+.drawer-foot{margin-top:auto; padding: 14px; border-top: 1px solid var(--border)}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns: 1fr;}
+  .hero-visual{min-height: 300px}
+  .trust-row{grid-template-columns: repeat(2, minmax(0, 1fr))}
+  .search-form{grid-template-columns: 1fr 1fr;}
+  .search-form .btn-lg{grid-column: 1 / -1}
+  .cards{grid-template-columns: repeat(2, minmax(0, 1fr))}
+  .steps{grid-template-columns: 1fr}
+  .quotes{grid-template-columns: 1fr}
+  .app-grid{grid-template-columns: 1fr}
+  .footer-grid{grid-template-columns: 1fr}
+  .footer-cols{grid-template-columns: repeat(2, minmax(0, 1fr))}
+}
+
+@media (max-width: 720px){
+  .nav{display:none}
+  .mobile-menu-btn{display:grid}
+  .hero{padding-top: 42px}
+  .search-surface{padding: 18px}
+  .search-form{grid-template-columns: 1fr}
+  .chip{position:static; transform:none; height: 40px; border-radius: 14px}
+  .control{gap:10px}
+  input, select{height: 54px}
+  .cards{grid-template-columns: 1fr}
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{transition:none !important; scroll-behavior:auto !important}
+}
+
*** End Patch
PATCH

